def links(item):
 result=[]
 for sid in item['source_ids']:
  title,url=S[sid]
  result.append(f'[{title}]({url})' if url else title)
 return '; '.join(result)

md=['# Своя компания — 20 категорий, 100 вопросов','',
 '**Для ведущего: здесь раскрыты ответы. Игрокам файл не показывать.**','',
 'Редакторская версия 2.0 от 7 ноября 2026 года. 6–7 игроков, каждый за себя. Два раунда, в каждом 10 категорий; в каждой категории по пять вопросов на 100–500.','',
 'Полный проход с обсуждениями: ориентировочно 100–140 минут. Для исходных 1–1,5 часа можно сыграть по три выбранных вопроса из каждой категории: всего 60. Весь банк из 100 вопросов при этом готов и доступен.','',
 'В обычных вопросах даём 20–30 секунд, в ребусах до 40. В «Очках за глаза» 7 секунд, в коротких киноописаниях 10. За верный ответ ведущий выдаёт цену вопроса; за ошибку для дружеского вечера предлагается не штрафовать.','',
 'Фотораунд «Цензор перестарался»: фото показывается с плашками; после ответа плашки убираются. В локальном HTML-документе это уже можно проверить. Фотооригиналы не редактировались. На схемах рук нет настоящих травм — это авторские рисунки.','',
 'Ребусы адаптированы для русского языка и нарисованы специально для пакета. Reddit служит источником механик и примеров обсуждения разгадок. Чужие английские карточки не выдаются за готовые русские задачи.','']
for r in rounds:
 md += [f"## Раунд {r['id']}",'','| Категория | Что внутри — только для ведущего |','|---|---|']
 for cid in r['category_ids']:
  c=cats[cid-1];md.append(f"| {c['title']} | {c['description']} |")
 md.append('')
 for cid in r['category_ids']:
  c=cats[cid-1];md += [f"### {c['title']}",'']
  for item in c['questions']:
   md += [f"#### {item['value']} баллов — {item['id']}",'',item['prompt'],'']
   if item['options']:md += ['Варианты: '+' / '.join(item['options'])+'.','']
   if item['media']:
    m=item['media'];md += [f"Картинка: [{Path(m['path']).name}]({(ROOT/m['path']).as_posix()}).",'']
    if m.get('question_masks_normalized'):md += ['Показать с плашками: '+str(m['question_masks_normalized'])+'. Координаты: x, y, ширина, высота от 0 до 1. В HTML-документе плашки уже наложены слоем.','']
   md += [f"**Ответ:** {item['answer']}.",'','**Зачёт:** '+'; '.join(item['accepted_answers'])+'.','',item['explanation'],'']
   if item['host_note']:md += ['**Ведущему:** '+item['host_note'],'']
   md += ['Источники: '+links(item)+'.','']
(ROOT/'ВИКТОРИНА_100_ВОПРОСОВ.md').write_text('\n'.join(md),encoding='utf-8')

style='''body{font:18px/1.55 Segoe UI,Arial,sans-serif;color:#182d3b;background:#f8f3e9;max-width:1120px;margin:40px auto;padding:0 24px}h1{line-height:1.15}h2{margin-top:64px;border-top:3px solid #182d3b;padding-top:25px}article{background:white;border:1px solid #dfd8cb;border-radius:18px;padding:26px;margin:26px 0}summary{cursor:pointer;font-weight:700;padding:12px 0;color:#155d8b}.stage{position:relative;display:inline-block;max-width:100%;line-height:0;background:#ddd}.stage img{display:block;max-width:100%;max-height:680px;width:auto;height:auto}.mask{position:absolute;background:#182d3b;border:2px solid #f3b941;box-sizing:border-box;display:flex;align-items:center;justify-content:center;color:white;font:700 42px Arial;z-index:1}.reveal{max-width:100%;max-height:780px;display:block;margin:16px 0}.small{font-size:14px;color:#536775}.tag{background:#edf3f7;padding:4px 10px;border-radius:20px}a{color:#155d8b}nav{columns:2}ol{padding-left:26px}details{margin-top:15px}.warning{background:#ffebbd;padding:20px;border-radius:12px}'''
h=[f'<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Проверка пакета — 100 вопросов</title><style>{style}</style><body>',
 '<h1>Своя компания</h1><p>20 категорий · 100 вопросов · два раунда</p><p class="warning"><b>Локальный документ ведущего.</b> Здесь есть ответы, источники и раскрытия. Это просмотр контента, не игровое табло. Игровой сайт пока не создавался.</p>',
 '<p>Полный проход: около 100–140 минут. Для 60–90 минут — по три выбранных вопроса из каждой категории. Названия на будущем игровом поле будут без поясняющих подзаголовков.</p><nav><ol>']
for c in cats:h.append(f'<li><a href="#c{c["id"]}">{escape(c["title"])}</a></li>')
h.append('</ol></nav>')
for r in rounds:
 h.append(f'<h2>Раунд {r["id"]}</h2>')
 for cid in r['category_ids']:
  c=cats[cid-1];h.append(f'<h2 id="c{cid}">{escape(c["title"])}</h2><p>{escape(c["description"])}</p>')
  for item in c['questions']:
   h.append(f'<article id="{item["id"]}"><span class="tag">{item["value"]} баллов</span><p>{escape(item["prompt"])}</p>')
   if item['options']:h.append('<p>'+escape(' / '.join(item['options']))+'</p>')
   m=item['media']
   if m:
    h.append(f'<div class="stage"><img src="{escape(m["path"])}" alt="Изображение к вопросу {item["id"]}" loading="lazy">')
    for x,y,w,hh in m.get('question_masks_normalized',[]):h.append(f'<span class="mask" style="left:{x*100}%;top:{y*100}%;width:{w*100}%;height:{hh*100}%">?</span>')
    h.append('</div>')
   h.append(f'<details><summary>Ответ и раскрытие</summary><p><b>{escape(item["answer"])}</b></p><p>{escape(item["explanation"])}</p><p class="small">Зачёт: {escape("; ".join(item["accepted_answers"]))}</p>')
   if m and m.get('question_masks_normalized'):h.append(f'<img class="reveal" src="{escape(m["path"])}" alt="{escape(item["answer"])}" loading="lazy">')
   if item['host_note']:h.append(f'<p class="small">Ведущему: {escape(item["host_note"])}</p>')
   for sid in item['source_ids']:
    title,url=S[sid]
    h.append(f'<p class="small"><a href="{escape(url)}" target="_blank" rel="noreferrer">{escape(title)}</a></p>' if url else f'<p class="small">{escape(title)}</p>')
   h.append('</details></article>')
h.append('</body></html>')
(ROOT/'ПРОСМОТР_ПАКЕТА.html').write_text('\n'.join(h),encoding='utf-8')

used={x['media']['source_id'] for c in cats for x in c['questions'] if x['media']}
records=json.loads((ROOT/'assets/image_sources.json').read_text(encoding='utf-8'))
credits=['# Используемые изображения и карточки','',f'В текущем пакете используется {len(used)} изображение/карточка. Старые магшоты не входят в пакет. Оригиналы фото сохранены без изменений; плашки в HTML — отдельный слой показа.','']
for a in records:
 a['used_in_current_pack']=a['id'] in used
 if a['id'] not in used:continue
 raw=(ROOT/a['path']).read_bytes();a['bytes']=len(raw);a['sha256']=hashlib.sha256(raw).hexdigest()
 clean=lambda t:re.sub('<[^>]*>','',t or '').strip()
 credits += [f"## {a['id']}",'',f"Файл: `{a['path']}`",'',f"Источник: [{a['title']}]({a['source_url']})" if a['source_url'] else 'Авторская векторная карточка для этой игры.','',f"Автор: {clean(a['author_html'])}",'',f"Лицензия по исходной карточке: {a['license']}",'']
 if a.get('license_url'):credits += [a['license_url'],'']
(ROOT/'assets/image_sources.json').write_text(json.dumps(records,ensure_ascii=False,indent=2),encoding='utf-8')
(ROOT/'assets/ИСТОЧНИКИ_ИЗОБРАЖЕНИЙ.md').write_text('\n'.join(credits),encoding='utf-8')
